new update:

If we force the code to use the same semaphores every time we run `iree_hal_level_zero_device_create_semaphore`:
```diff
@@ -293,8 +294,12 @@ static iree_status_t iree_hal_level_zero_device_create_semaphore(
     iree_hal_semaphore_t** out_semaphore) {
   iree_hal_level_zero_device_t* device =
       iree_hal_level_zero_device_cast(base_device);
-  return iree_hal_level_zero_semaphore_create(&device->context_wrapper,
-                                              initial_value, out_semaphore);
+  if(device->semaphore == NULL) {
+    iree_hal_level_zero_semaphore_create(&device->context_wrapper,
+                                                initial_value, &device->semaphore);
+  }
+  *out_semaphore = device->semaphore;
+  return iree_ok_status();
 }
 ```
 It works 🤔

